package com.sistemahospitalar.hospital.model;
import com.sistemahospitalar.hospital.model.enums.*; import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*;
@Entity @Getter @Setter @NoArgsConstructor
public class Quarto { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Column(nullable=false,unique=true,length=20) private String numero; @Min(1) @Column(nullable=false) private int capacidade; @Min(0) @Column(nullable=false) private int leitosOcupados; @Enumerated(EnumType.STRING) @Column(nullable=false) private SituacaoQuartoEnum situacao=SituacaoQuartoEnum.DISPONIVEL; public boolean temVagaDisponivel(){return situacao!=SituacaoQuartoEnum.MANUTENCAO && leitosOcupados<capacidade;} public void ocuparLeito(){if(!temVagaDisponivel()) throw new IllegalStateException("Quarto sem vaga disponível."); leitosOcupados++; situacao=leitosOcupados>=capacidade?SituacaoQuartoEnum.OCUPADO:SituacaoQuartoEnum.DISPONIVEL;} public void liberarLeito(){if(leitosOcupados>0) leitosOcupados--; situacao=SituacaoQuartoEnum.DISPONIVEL;} }
